import{_ as c,l,o as r,c as i,v as o,p as s,x as e,d as n,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const R=JSON.parse('{"title":"Reactor / Proactor","description":"","frontmatter":{"title":"Reactor / Proactor","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/reactor-proactor.md","filePath":"cs/reactor-proactor.md","lastUpdated":1789023840000}'),h={name:"cs/reactor-proactor.md"};function P(_,a,u,m,f,A){const t=l("Mermaid");return r(),i("div",null,[a[1]||(a[1]=o('<h1 id="reactor-proactor" tabindex="-1">Reactor / Proactor <a class="header-anchor" href="#reactor-proactor" aria-label="Permalink to &quot;Reactor / Proactor&quot;">​</a></h1><div class="epigraph"><p>Reactor 等就绪再同步读写；Proactor 把异步完成当事件。两者把「一线程一连接」换成事件循环，才能接近线速套接字。</p><footer>—— 据 Schmidt, Reactor, POSA2；Proactor 模式对照；Stevens UNP 整理</footer></div><p>主干<a href="/cs/socket-nonblock">非阻塞套接字</a> 已给 O_NONBLOCK。<a href="/cs/network-simulation">上一课</a> 不写主机程序。缺口是<strong>事件分派模式</strong>：select/epoll vs IOCP/io_uring。本课不把 C10K 数字写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>阻塞 <code>recv</code> 一连接一线程，万连接炸栈。<a href="/cs/socket-nonblock">非阻塞</a> 要自己问谁就绪。Reactor：多路复用（epoll）→ 分派 handler → 非阻塞 I/O。Proactor：提交异步读，完成队列回调，数据已在缓冲。Linux 历史偏 Reactor，io_uring 靠向 Proactor。TSO/GRO 减事件次数。</p><p>不要把模式写成语言框架名。</p><p><span class="marginnote">POSA2 Reactor。本课不把每套 API 参数背完。</span></p><h3 id="i-o-线程必须短" tabindex="-1">I/O 线程必须短 <a class="header-anchor" href="#i-o-线程必须短" aria-label="Permalink to &quot;I/O 线程必须短&quot;">​</a></h3><p>就绪再读 vs 完成再回调。循环里阻塞 DNS 会冻整服务。重 CPU 应下到线程池。不是语言框架名。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照两种时序图。画：等待 → 就绪/完成 → 处理。与交换机：都是事件驱动，一层主机，一层 ASIC。</p>',11)),(r(),s(d,null,{default:e(()=>[p(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20RX%5B%22Reactor%3A%20%E5%B0%B1%E7%BB%AA%E5%88%99%E8%AF%BB%22%5D%20--%3E%20H%5B%22handler%22%5D%0A%20%20PX%5B%22Proactor%3A%20%E5%AE%8C%E6%88%90%E5%88%99%E5%9B%9E%E8%B0%83%22%5D%20--%3E%20H%0A%20%20MX%5B%22epoll%2FIOCP%22%5D%20--%3E%20RX%0A%20%20MX%20--%3E%20PX%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>反向代理、QUIC 用户态栈都是这种循环。SSH 按键也是。线程池可放在 handler 后做业务，I/O 线程不阻塞——否则 Reactor 假死。与 PTP 无关。</p><p>安全：事件循环里不要做重 CPU，否则延迟像膨胀。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入每种开源库。C10K 与并发模型是下一课。后课默认：高并发 I/O 用 Reactor 或 Proactor，不是一连接一线程。</p><p>在循环里再阻塞 DNS 查询会把整个服务卡住。</p><p>上一课留下的缺口在本课收口；「Reactor / Proactor」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/c10k-concurrency">C10K 与并发模型</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Reactor 等就绪；Proactor 等完成。</li><li>多路复用是共同前提。</li><li>I/O 线程必须短而非阻塞。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Schmidt Reactor；UNP。</li></ul>',10))])}const E=c(h,[["render",P]]);export{R as __pageData,E as default};
